using System;
using System.IO;
using System.Reflection;
using HundredTiles.Core;
using HundredTiles.WorkshopCompatibility;
class ObjectCapacityChecks {
 static string root;
 static Assembly Resolve(object s,ResolveEventArgs a){string p=Path.Combine(root,new AssemblyName(a.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;}
 static int Main(string[] args){root=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=Resolve;try{return Run();}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static int Run(){foreach(int n in new[]{262144,524288,2097152}){var trees=new ObjectPositionRecord[n];var props=new ObjectPositionRecord[65536];var binding=new byte[32];trees[n-1]=new ObjectPositionRecord{Flags=1,X=PackedObjectPosition.Encode(9000f),Z=PackedObjectPosition.Encode(100f)};byte[] bytes=ExpandedObjects.Encode(trees,props,binding);if(n==262144){var v1=ObjectPositionCodec.Encode(trees,props,binding);if(Convert.ToBase64String(v1)!=Convert.ToBase64String(bytes))throw new Exception("V1 output changed.");}ObjectPositionRecord[] t,p;ExpandedObjects.Decode(bytes,ObjectPositionCodec.Project(trees),ObjectPositionCodec.Project(props),binding,out t,out p);if(t.Length!=n || !t[n-1].X.PositiveExtension)throw new Exception("Expanded coordinate lost.");var bad=(byte[])bytes.Clone();bad[bad.Length-1]^=1;bool rejected=false;try{ExpandedObjects.Decode(bad,ObjectPositionCodec.Project(trees),ObjectPositionCodec.Project(props),binding,out t,out p);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Corruption accepted.");Console.WriteLine("PASS tree capacity "+n+": format, projection, binding, corruption rejection.");}
 var small=new ObjectPositionRecord[262144];var props2=new ObjectPositionRecord[65536];var bind=new byte[32];small[10]=new ObjectPositionRecord{Flags=1,X=PackedObjectPosition.Encode(9000),Z=PackedObjectPosition.Encode(0)};var old=ExpandedObjects.Encode(small,props2,bind);var larger=new ObjectPositionRecord[524288];Array.Copy(ObjectPositionCodec.Project(small),larger,small.Length);ObjectPositionRecord[] mt,mp;ExpandedObjects.Decode(old,larger,props2,bind,out mt,out mp);if(mt.Length!=524288 || !mt[10].X.PositiveExtension)throw new Exception("V1 capacity migration lost coordinates.");larger[300000].Flags=1;bool refused=false;try{ExpandedObjects.Decode(old,larger,props2,bind,out mt,out mp);}catch(InvalidDataException){refused=true;}if(!refused)throw new Exception("Occupied new slots overwritten.");Console.WriteLine("PASS legacy capacity migration; occupied additional slots rejected.");return 0;}
}
